    "source": "// ◐ META — this composition IS the playground you are looking at.\n//\n// In meta mode the result pane's tabs are not JavaScript: each *View\n// component below owns one tab, mounted by an `effect … undo …` pair — so\n// unloading a view removes its tab from the page, LIFO, and the no-residue\n// proof is visible in the DOM. Tab clicks route through the `tabs` service:\n// every click you make shows up in the trace as an audited host crossing.\n//\n// You are editing the UI you are using. Try it:\n//   · rename a label (\"Diagnostics\" → \"Verdicts\"), press ⇄ Swap — live\n//   · delete the IRView component, press ⇄ Swap — the IR tab is gone\n//   · press ■ Unload — the whole pane unbuilds itself, backwards, and the\n//     residue checks pass because every mount carried its unmount\n//\n// The DOM is host territory, so it is reached only through the externs at\n// the bottom — open the G8 audit (while it still has a tab…) and the\n// playground will enumerate its own boundary surface.\n\nservice Tabs {\n  fn active() -> Str\n  emission fn select(id: Str)\n}\n\ncomponent TabRouter provides tabs: Tabs {\n  let current = effect Map.new() undo current.drop()\n\n  provide tabs {\n    fn active() = current.get(\"now\") ?? \"diagnostics\"\n    fn select(id) {\n      effect current.insert(\"now\", id)\n      undo   current.remove(\"now\")\n      emit ui_select(id)\n    }\n  }\n}\n\ncomponent DiagnosticsView requires tabs: Tabs {\n  let slot = effect ui_mount(\"diagnostics\", \"Diagnostics\")\n             undo   ui_unmount(\"diagnostics\")\n}\n\ncomponent AuditView requires tabs: Tabs {\n  let slot = effect ui_mount(\"audit\", \"G8 audit\")\n             undo   ui_unmount(\"audit\")\n}\n\ncomponent PlanView requires tabs: Tabs {\n  let slot = effect ui_mount(\"plan\", \"Plan\")\n             undo   ui_unmount(\"plan\")\n}\n\ncomponent IRView requires tabs: Tabs {\n  let slot = effect ui_mount(\"ir\", \"IR\")\n             undo   ui_unmount(\"ir\")\n}\n\n// ---------- the host boundary (G8) — the only way this UI touches the DOM\n\nextern pure fn ui_unmount(id: Str) -> Int\n  = @py { import playground_host; return playground_host.unmount(id) }\n\nextern acquire fn ui_mount(id: Str, label: Str) -> Int undo ui_unmount(\"\")\n  = @py { import playground_host; return playground_host.mount(id, label) }\n\nextern emission fn ui_select(id: Str)\n  = @py { import playground_host; playground_host.select(id) }\n"
