    "kind": "accept",
    "file": "user_cache.rvl",
    "source": "// The v0 demo pair: a database provider and a cache built on it.\n// Swap PgDatabase for another Database provider at runtime and UserCache\n// deactivates (LIFO, db still readable during its teardown) and reactivates\n// against the replacement. Unload both and the environment is recovered.\n\nservice Database {\n  fn query(sql: Str) -> List[Row]\n  emission fn execute(sql: Str) -> Int\n}\n\nservice Cache {\n  fn get(key: Str) -> Opt[Str]\n  // emission: `put` writes the cache log through `db` (a service\n  // declaration is an upper bound on what its providers may do)\n  emission fn put(key: Str, value: Str)\n}\n\ncomponent PgDatabase provides db: Database {\n  config { url: Str, pool_size: Int = 10 }\n\n  let pool = effect Pool.open(config.url, config.pool_size)\n             undo   pool.close()\n\n  provide db {\n    fn query(sql)   = pool.query(sql)\n    fn execute(sql) = pool.execute(sql)\n  }\n}\n\ncomponent UserCache requires db: Database provides cache: Cache {\n  let store = effect Map.new() undo store.drop()\n\n  provide cache {\n    fn get(key) = store.get(key)\n    fn put(key, value) {\n      effect store.insert(key, value)\n      undo   store.remove(key)\n      emit db.execute(`INSERT INTO cache_log VALUES (${key})`)\n    }\n  }\n}\n"
