    "kind": "accept",
    "file": "tenant_attenuation.rvl",
    "source": "// Capability attenuation on spawn (docs/capability-attenuation.md, item 66).\n//\n// A multi-tenant router holds two key-value boundaries — `kv_a` and `kv_b`.\n// It spawns one worker instance per tenant. Each worker template reaches only\n// its own tenant's store, so the spawn *narrows*: the `tenant_a` instance is\n// granted `kv_a` and provably cannot reach `kv_b`, even though the router that\n// spawned it holds both. Least-authority per instance, for free.\n//\n// `revl audit examples/tenant_attenuation.rvl` shows the attenuation chain:\n//   Router → TenantAWorker: holds [kv_a, kv_b] ⊇ grants [kv_a]  (dropped: kv_b)\n//   Router → TenantBWorker: holds [kv_a, kv_b] ⊇ grants [kv_b]  (dropped: kv_a)\n\nservice Store {\n  emission[kv_a] fn write_a(row: Str) -> Int\n}\n\nservice StoreB {\n  emission[kv_b] fn write_b(row: Str) -> Int\n}\n\nservice Worker {\n  emission fn tenant() -> Str\n}\n\n// Each worker requires exactly one tenant store and reaches only that boundary.\ncomponent TenantAWorker requires kv_a: Store provides worker: Worker {\n  config { tag: Str }\n  provide worker {\n    fn tenant() {\n      emit kv_a.write_a(\"hello from a\")\n      return \"a\"\n    }\n  }\n}\n\ncomponent TenantBWorker requires kv_b: StoreB provides worker: Worker {\n  config { tag: Str }\n  provide worker {\n    fn tenant() {\n      emit kv_b.write_b(\"hello from b\")\n      return \"b\"\n    }\n  }\n}\n\n// The router holds BOTH boundaries, but passes each instance only its own.\ncomponent Router requires kv_a: Store requires kv_b: StoreB {\n  let a = effect spawn TenantAWorker with { tag: \"a\" } undo a.dispose()\n  let b = effect spawn TenantBWorker with { tag: \"b\" } undo b.dispose()\n}\n"
