    "id": "durable_log",
    "label": "durable resources — acquire and the two undos",
    "kind": "accept",
    "file": "durable_log.rvl",
    "source": "// The acquire/undo discipline for a durable host resource with state\n// (roadmap item 83; docs/syntax-2.0.md §6, \"acquire and the two undos\").\n//\n// The resource is a real file handle. `log_open` opens an append-only audit\n// log and returns its OS file descriptor; `log_write` appends a line through\n// that fd; `log_close` releases it. The fd is state that outlives the call\n// that produced it, so releasing it correctly is the whole point.\n//\n// Two undos are in play, and only one of them is real:\n//\n//   * the extern's `undo log_close(1)` — G4 requires an `acquire` extern to\n//     carry an undo, but an acquire's teardown sees only the implicit\n//     `result` binding, and the literal `1` written here can never be the\n//     descriptor the runtime actually handed back. This slot is DOCUMENTATION:\n//     it names the inverse operation, not a working release.\n//\n//   * the component's `let fd = effect log_open(...) undo log_close(fd)` — the\n//     REAL revertible acquisition. `fd` is the descriptor the acquire returned,\n//     in scope, so this undo closes the handle that was actually opened. This\n//     is what the lifecycle machinery runs on teardown, and what `no_residue`\n//     checks reverted.\n//\n// The discipline: thread the acquired handle through the component effect and\n// close it there. The extern undo documents intent; the component effect does\n// the work.\n\nextern pure fn log_close(fd: Int)\n= @py {\n      import os\n      try:\n          os.close(fd)\n      except OSError:\n          pass\n      return None\n    }\n\nextern pure fn log_write(fd: Int, line: Str) -> Int\n= @py {\n      import os\n      return os.write(fd, (line + \"\\n\").encode(\"utf-8\"))\n    }\n\nextern acquire fn log_open(path: Str) -> Int undo log_close(1)\n= @py {\n      import os\n      return os.open(path, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o644)\n    }\n\nservice AuditLog {\n  emission fn record(line: Str) -> Int\n}\n\ncomponent FileAuditLog provides audit: AuditLog {\n  config { path: Str }\n\n  // The acquired fd is threaded into the undo — this closes the handle that\n  // was really opened, unlike the extern's documentary `log_close(1)`.\n  let fd = effect log_open(config.path) undo log_close(fd)\n\n  provide audit {\n    fn record(line) = log_write(fd, line)\n  }\n}\n\nlifecycle test \"the audit log opens, records, and closes cleanly\" {\n  load FileAuditLog with { path: \"/tmp/revl-durable-log.audit\" }\n  let n = call audit.record(\"boot\")\n  assert n > 0\n  unload FileAuditLog\n  assert no_residue\n}\n"
